  bind('[data-add]','click',()=>add(q('[data-add-type]').value));
  bind('[data-configure]','click',()=>{const next=coordinator.document,b=next.sections.find(s=>s.blocks[selected]).blocks[selected];b.content={label:q('[data-label]').value,href:q('[data-href]').value};b.presentation={variant:q('[data-variant]').value};coordinator.transact('Edit button',next);});
  bind('[data-configure-image]','click',()=>{const next=coordinator.document,b=next.sections.find(s=>s.blocks[selected]).blocks[selected];b.content=JSON.parse(q('[data-image]').value);b.presentation={fit:q('[data-fit]').value};coordinator.transact('Edit image',next);});
